// src/components/SpendingPriority.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority({ formData, updateData }) {
  const navigate = useNavigate();
  const [priorities, setPriorities] = useState({});
  const categories = Array.isArray(formData.category) ? formData.category : [formData.category];

  useEffect(() => {
    const initial = {};
    categories.forEach(cat => initial[cat] = formData.spendingPriority?.[cat] || 0);
    setPriorities(initial);
  }, [formData, categories]);

  const handleSliderChange = (cat, value) => setPriorities(prev => ({ ...prev, [cat]: Number(value) }));

  const handleNext = () => {
    updateData({ spendingPriority: priorities });
    navigate("/budget");
  };

  if (!categories.length) return <p style={{ color: "red", textAlign: "center" }}>No income categories selected</p>;

  return (
    <div className="spending-container">
      <h2 className="spending-title">Set Your Spending Priorities</h2>
      <div className="spending-grid">
        {categories.map(cat => (
          <div key={cat} className="spending-card">
            <h3 className="spending-name">{cat}</h3>
            <input type="range" min={0} max={5} value={priorities[cat]} onChange={e => handleSliderChange(cat, e.target.value)} className="spending-slider" />
            <p>Priority: {priorities[cat]}</p>
          </div>
        ))}
      </div>
      <button className="next-button" onClick={handleNext}>Continue</button>
    </div>
  );
}

export default SpendingPriority;
